select public.add_site_release('1.3.0','Билеты классу: прохождение билета в Telegram',
  jsonb_build_array(
    jsonb_build_object('kind','new','scope','site','min_rank',1,'text','Новый раздел «Билеты классу»: запустите сохранённый набор для класса по ссылке или QR-коду, ученики ждут в зале ожидания, вы видите, у кого какой вариант, меняете его при необходимости, выбираете время от 5 до 45 минут и нажимаете «Начать» — у всех идёт общий отсчёт и билет открывается одновременно; результаты в таблице в реальном времени, разбор по вопросам, выгрузка в Excel и отправка ученикам разбора их ошибок.'),
    jsonb_build_object('kind','new','scope','bot','min_rank',1,'text','Ученик может пройти билет прямо в Telegram по ссылке от преподавателя: сначала зал ожидания с номером своего варианта, затем по команде преподавателя отсчёт 3-2-1 и билет с общим временем; варианты ответов у каждого перемешаны, баллы видны сразу после сдачи, а разбор ошибок приходит, когда его отправит преподаватель.')
  ),
  '2026-11-23 10:00:00+05');
